package scale

// The 12-note chromatic scale expressed with sharps and with flats.
var (
	sharpChromatic = []string{"C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"}
	flatChromatic  = []string{"C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B"}
)

// Tonics (in their given casing) whose scale is expressed with flats.
// An uppercase first letter selects the major key signature; a lowercase
// first letter selects the minor key signature. Every other tonic uses
// the sharp expression (including the natural "C" and "a", which follow
// the sharps when ascending).
var (
	majorFlats = map[string]bool{"F": true, "Bb": true, "Eb": true, "Ab": true, "Db": true, "Gb": true}
	minorFlats = map[string]bool{"d": true, "g": true, "c": true, "f": true, "bb": true, "eb": true}
)

// noteIndex maps a note name (in output form) to its pitch-class index.
var noteIndex = map[string]int{
	"C": 0, "C#": 1, "Db": 1,
	"D": 2, "D#": 3, "Eb": 3,
	"E": 4,
	"F": 5, "F#": 6, "Gb": 6,
	"G": 7, "G#": 8, "Ab": 8,
	"A": 9, "A#": 10, "Bb": 10,
	"B": 11,
}

// Scale generates the musical scale starting at the given tonic and
// following the specified interval pattern. An empty interval produces
// the full 12-note chromatic scale.
func Scale(tonic, interval string) []string {
	chromatic := sharpChromatic
	if usesFlats(tonic) {
		chromatic = flatChromatic
	}
	start := noteIndex[normalize(tonic)]

	if interval == "" {
		result := make([]string, 0, 12)
		for i := 0; i < 12; i++ {
			result = append(result, chromatic[(start+i)%12])
		}
		return result
	}

	result := []string{chromatic[start]}
	current := start
	for _, c := range interval {
		current = (current + semitones(c)) % 12
		result = append(result, chromatic[current])
	}
	return result
}

// usesFlats reports whether the scale for the given tonic should be
// expressed with flats.
func usesFlats(tonic string) bool {
	if tonic == "" {
		return false
	}
	if isUpper(tonic[0]) {
		return majorFlats[tonic]
	}
	return minorFlats[tonic]
}

// normalize uppercases the first letter of the tonic, leaving any
// accidental (# or b) untouched.
func normalize(tonic string) string {
	if tonic == "" {
		return ""
	}
	b := []byte(tonic)
	b[0] = upper(b[0])
	return string(b)
}

func isUpper(c byte) bool {
	return c >= 'A' && c <= 'Z'
}

func upper(c byte) byte {
	if c >= 'a' && c <= 'z' {
		return c - 'a' + 'A'
	}
	return c
}

// semitones returns the number of semitones for an interval character.
func semitones(c byte) int {
	switch c {
	case 'm': // half step (minor second)
		return 1
	case 'M': // whole step (major second)
		return 2
	case 'A': // augmented second
		return 3
	}
	return 0
}

